import{_ as o,o as a,c,a2 as d}from"./chunks/framework.C0KMm31j.js";const t="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_costmap_2d_source_01_boundary.png",r="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_costmap_2d_source_02_lifecycle.png",i="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_costmap_2d_source_03_layered_update.png",n="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_costmap_2d_source_04_sensor_layers.png",l="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_costmap_2d_source_05_inflation_denoise.png",s="/Nav2ArticlesSite/article-assets/2026-07-24/nav2_costmap_2d_source_06_filters_outputs.png",y=JSON.parse('{"title":"一张代价地图，如何同时听懂地图、雷达与禁行区？逐函数拆解 nav2_costmap_2d","description":"规划器看到的不是激光点，也不是原始地图，而是一张每个栅格都带有风险代价的二维数组。nav2costmap2d 的工作，就是把静态地图、LaserScan、PointCloud2、Range、机器人 Footprint、禁行区和速度区统一翻译成这张数组，再把它交给 Planner、Controller","frontmatter":{"title":"一张代价地图，如何同时听懂地图、雷达与禁行区？逐函数拆解 nav2_costmap_2d","description":"规划器看到的不是激光点，也不是原始地图，而是一张每个栅格都带有风险代价的二维数组。nav2costmap2d 的工作，就是把静态地图、LaserScan、PointCloud2、Range、机器人 Footprint、禁行区和速度区统一翻译成这张数组，再把它交给 Planner、Controller","date":"2026-07-24","section":"四 · 代价地图与安全","readingTime":23,"source":"2026-07-24/nav2_costmap_2d_source_walkthrough.md","status":"published","cover":"/article-assets/2026-07-24/nav2_costmap_2d_source_01_boundary.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-costmap-2d-source-walkthrough"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"一张代价地图，如何同时听懂地图、雷达与禁行区？逐函数拆解 nav2_costmap_2d"}],["meta",{"property":"og:description","content":"规划器看到的不是激光点，也不是原始地图，而是一张每个栅格都带有风险代价的二维数组。nav2costmap2d 的工作，就是把静态地图、LaserScan、PointCloud2、Range、机器人 Footprint、禁行区和速度区统一翻译成这张数组，再把它交给 Planner、Controller"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-costmap-2d-source-walkthrough"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-24/nav2_costmap_2d_source_01_boundary.png"}],["meta",{"property":"article:published_time","content":"2026-07-24"}],["meta",{"name":"twitter:title","content":"一张代价地图，如何同时听懂地图、雷达与禁行区？逐函数拆解 nav2_costmap_2d"}],["meta",{"name":"twitter:description","content":"规划器看到的不是激光点，也不是原始地图，而是一张每个栅格都带有风险代价的二维数组。nav2costmap2d 的工作，就是把静态地图、LaserScan、PointCloud2、Range、机器人 Footprint、禁行区和速度区统一翻译成这张数组，再把它交给 Planner、Controller"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-24/nav2_costmap_2d_source_01_boundary.png"}]],"prev":{"text":"一束激光怎样变成避障代价？拆解 `nav2_costmap_2d` 调用全数据流","link":"/nav2/nav2-costmap-2d-full-dataflow"},"next":{"text":"机器人还没撞上，速度为何先被“截胡”？逐函数拆解 Nav2 Collision Monitor 的 74 个入口","link":"/nav2/nav2-collision-monitor-74-entries-source-walkthrough"}},"headers":[],"relativePath":"nav2/nav2-costmap-2d-source-walkthrough.md","filePath":"nav2/nav2-costmap-2d-source-walkthrough.md","lastUpdated":null}'),p={name:"nav2/nav2-costmap-2d-source-walkthrough.md"};function u(m,e,h,b,_,f){return a(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="一张代价地图-如何同时听懂地图、雷达与禁行区-逐函数拆解-nav2-costmap-2d" tabindex="-1">一张代价地图，如何同时听懂地图、雷达与禁行区？逐函数拆解 nav2_costmap_2d <a class="header-anchor" href="#一张代价地图-如何同时听懂地图、雷达与禁行区-逐函数拆解-nav2-costmap-2d" aria-label="Permalink to &quot;一张代价地图，如何同时听懂地图、雷达与禁行区？逐函数拆解 nav2_costmap_2d&quot;">​</a></h1><p>规划器看到的不是激光点，也不是原始地图，而是一张每个栅格都带有风险代价的二维数组。<code>nav2_costmap_2d</code> 的工作，就是把静态地图、LaserScan、PointCloud2、Range、机器人 Footprint、禁行区和速度区统一翻译成这张数组，再把它交给 Planner、Controller、碰撞检查器和可视化工具。</p><p>本文以当前工程中的 <code>nav2_costmap_2d 1.1.20</code> 为准。测试函数、基准程序和插件注册宏不展开；生产 <code>.cpp</code>、头文件内联函数、模板算法、回调与三个可执行入口均纳入审计。重载函数分别核对，职责相同的 getter、坐标转换和模板辅助函数按函数族合并说明。</p><p><img src="'+t+'" alt="nav2_costmap_2d 包边界与总数据流"></p><h2 id="一、先看清包边界-它负责融合-不负责规划" tabindex="-1">一、先看清包边界：它负责融合，不负责规划 <a class="header-anchor" href="#一、先看清包边界-它负责融合-不负责规划" aria-label="Permalink to &quot;一、先看清包边界：它负责融合，不负责规划&quot;">​</a></h2><h3 id="_1-1-输入数据从哪里来" tabindex="-1">1.1 输入数据从哪里来 <a class="header-anchor" href="#_1-1-输入数据从哪里来" aria-label="Permalink to &quot;1.1 输入数据从哪里来&quot;">​</a></h3><p><code>StaticLayer::incomingMap()</code> 和 <code>incomingUpdate()</code> 接收 <code>nav_msgs::msg::OccupancyGrid</code> 与 <code>map_msgs::msg::OccupancyGridUpdate</code>。消息通常由包外的 Map Server 发布，本包只校验、转换和缓存。</p><p><code>ObstacleLayer::laserScanCallback()</code>、<code>laserScanValidInfCallback()</code> 与 <code>pointCloud2Callback()</code> 接收 LaserScan 或 PointCloud2。LaserScan 通过包外 <code>laser_geometry::LaserProjection</code> 转成点云，<code>tf2_ros::MessageFilter</code> 负责等待坐标变换可用。</p><p><code>VoxelLayer</code> 复用 ObstacleLayer 的观测入口，却把点写入包外 <code>nav2_voxel_grid::VoxelGrid</code>。<code>RangeSensorLayer::bufferIncomingRangeMsg()</code> 接收超声波或红外 Range 消息。</p><p><code>CostmapFilterInfo</code> 与过滤 Mask 来自包外 Filter Info Server 和 Map Server。Keepout、Speed、Binary Filter 只消费这些 Topic，不负责生成 Mask。</p><h3 id="_1-2-输出数据流向哪里" tabindex="-1">1.2 输出数据流向哪里 <a class="header-anchor" href="#_1-2-输出数据流向哪里" aria-label="Permalink to &quot;1.2 输出数据流向哪里&quot;">​</a></h3><p><code>Costmap2DPublisher::prepareGrid()</code> 把内部 <code>0～255</code> 代价转换成 OccupancyGrid 的 <code>-1～100</code>；<code>prepareCostmap()</code> 保留原始代价值生成 <code>nav2_msgs::msg::Costmap</code>；<code>publishCostmap()</code> 根据尺寸、原点和更新窗口决定发送全图还是 <code>OccupancyGridUpdate</code>。</p><p><code>Costmap2DPublisher::costmap_service_callback()</code> 响应 <code>nav2_msgs::srv::GetCostmap</code>，忽略空请求内容，从 master costmap 拷贝时间、Frame、尺寸、分辨率、原点和原始代价数组。<code>active()</code> 只返回成员 <code>active_</code>；当前实现仅在构造时把它置为 false，Lifecycle 激活与停用函数没有改写该成员，因此不能用它判断发布器的真实激活状态。</p><p>Planner Server 与 Controller Server 通过包外 <code>Costmap2DROS</code> 接口读取 master costmap、机器人位姿和 current 状态。SpeedFilter 不改速度本身，而是发布 <code>nav2_msgs::msg::SpeedLimit</code>，由 Controller Server 再传给控制器插件。</p><p><code>CostmapTopicCollisionChecker</code> 是客户端路径：订阅 raw costmap 与 Footprint，在本地构造碰撞检查器。它不参与 Costmap Server 的周期融合。</p><h3 id="_1-3-pluginlib-加载了什么" tabindex="-1">1.3 pluginlib 加载了什么 <a class="header-anchor" href="#_1-3-pluginlib-加载了什么" aria-label="Permalink to &quot;1.3 pluginlib 加载了什么&quot;">​</a></h3><p><code>costmap_plugins.xml</code> 导出六个 Layer：Static、Obstacle、Voxel、Range、Inflation、Denoise；再导出 Keepout、Speed、Binary 三个 Filter。它们的共同基类是 <code>Layer</code>。</p><p>包外 <code>pluginlib::ClassLoader</code> 在 <code>Costmap2DROS::on_configure()</code> 中按参数顺序实例化。插件顺序会改变结果：常见链路是静态层与传感器层先写障碍，Inflation 后扩展安全代价，Filter 最后对融合结果施加语义约束。</p><h2 id="二、costmap2d-所有算法最终都落到一块-unsigned-char-数组" tabindex="-1">二、Costmap2D：所有算法最终都落到一块 unsigned char 数组 <a class="header-anchor" href="#二、costmap2d-所有算法最终都落到一块-unsigned-char-数组" aria-label="Permalink to &quot;二、Costmap2D：所有算法最终都落到一块 unsigned char 数组&quot;">​</a></h2><h3 id="_2-1-构造、复制和内存生命周期" tabindex="-1">2.1 构造、复制和内存生命周期 <a class="header-anchor" href="#_2-1-构造、复制和内存生命周期" aria-label="Permalink to &quot;2.1 构造、复制和内存生命周期&quot;">​</a></h3><p><code>Costmap2D()</code> 创建空对象；带尺寸构造函数保存宽、高、分辨率、原点和默认值，再调用 <code>initMaps()</code> 与 <code>resetMaps()</code>。OccupancyGrid 构造函数把包外消息的未知、空闲、占用值线性映射为 <code>NO_INFORMATION</code>、<code>FREE_SPACE</code> 到 <code>LETHAL_OBSTACLE</code>。</p><p>拷贝构造和 <code>operator=()</code> 复制元数据与整张数组；自赋值直接返回。<code>~Costmap2D()</code> 调用 <code>deleteMaps()</code> 并释放递归互斥量。<code>initMaps()</code> 重新分配数组，<code>deleteMaps()</code> 在锁内释放数组，<code>getMutex()</code> 把同一把递归锁提供给图层和发布器。</p><p><code>resizeMap()</code> 修改几何信息后重建并重置地图。<code>resetMaps()</code> 用 <code>default_value_</code> 填满整图；<code>resetMap()</code> 使用默认值清区域；<code>resetMapToValue()</code> 把指定矩形写成调用方给定的值。<code>setDefaultValue()</code> 与 <code>getDefaultValue()</code> 只管理后续重置使用的背景值。</p><h3 id="_2-2-单元格访问和坐标转换" tabindex="-1">2.2 单元格访问和坐标转换 <a class="header-anchor" href="#_2-2-单元格访问和坐标转换" aria-label="Permalink to &quot;2.2 单元格访问和坐标转换&quot;">​</a></h3><p><code>getIndex()</code> 接收 <code>mx</code>、<code>my</code>，把二维坐标展平为 <code>my * size_x + mx</code>；<code>indexToCells()</code> 做逆变换。<code>getCharMap()</code> 暴露底层数组指针，<code>getCost()</code> 两个重载分别按坐标或线性索引读取，<code>setCost()</code> 写入单元格。</p><p><code>mapToWorld()</code> 返回栅格中心的世界坐标。<code>worldToMap()</code> 检查原点和边界，失败时返回 false；<code>worldToMapNoBounds()</code> 允许得到负索引或越界索引；<code>worldToMapEnforceBounds()</code> 把结果夹在合法范围。三者语义不能混用：传感器更新常需先保留越界几何，真正写数组前才裁剪。</p><p><code>cellDistance()</code> 把米换算为栅格数。尺寸、原点和分辨率 getter 分别返回 cell 尺寸、米制尺寸、<code>origin_x</code>、<code>origin_y</code> 与 <code>resolution</code>。米制尺寸返回的是最后一个合法栅格中心，不是简单的宽度乘分辨率。</p><h3 id="_2-3-滚动窗口和局部复制" tabindex="-1">2.3 滚动窗口和局部复制 <a class="header-anchor" href="#_2-3-滚动窗口和局部复制" aria-label="Permalink to &quot;2.3 滚动窗口和局部复制&quot;">​</a></h3><p><code>updateOrigin()</code> 把新原点对齐到栅格，计算新旧窗口重叠区域，把重叠数据临时复制出来，重置整图，再写回新位置。这样机器人移动时可以保留仍位于窗口内的障碍。</p><p><code>copyMapRegion()</code> 是逐行 <code>memcpy</code> 模板；<code>copyWindow()</code> 在源、目标边界合法时复制 cell 矩形；<code>copyCostmapWindow()</code> 用世界坐标定义窗口，并把当前对象重建成源地图的子窗口。自窗口化和越界窗口返回 false。</p><h3 id="_2-4-射线与多边形" tabindex="-1">2.4 射线与多边形 <a class="header-anchor" href="#_2-4-射线与多边形" aria-label="Permalink to &quot;2.4 射线与多边形&quot;">​</a></h3><p><code>raytraceLine()</code> 计算射线起止偏移、最短与最长长度，再按主轴选择 Bresenham 方向。<code>bresenham2D()</code> 逐格调用 Functor；内部 <code>sign()</code> 决定索引步进方向。<code>MarkCell::operator()()</code> 把经过的格子写成指定代价，<code>PolygonOutlineCells::operator()()</code> 把索引转换成轮廓 cell。</p><p><code>polygonOutlineCells()</code> 对多边形每条边执行射线；<code>convexFillCells()</code> 先取得轮廓，再按列扫描填充凸多边形；<code>setConvexPolygonCost()</code> 先把世界顶点转换为栅格，任何顶点越界都返回 false，否则统一写入目标代价。</p><p><code>saveMap()</code> 把内部数组保存成 PGM，适合调试快照，不是 Costmap Server 的周期输出。</p><h2 id="三、costmap2dros-lifecycle、tf、线程与通信的总调度器" tabindex="-1">三、Costmap2DROS：Lifecycle、TF、线程与通信的总调度器 <a class="header-anchor" href="#三、costmap2dros-lifecycle、tf、线程与通信的总调度器" aria-label="Permalink to &quot;三、Costmap2DROS：Lifecycle、TF、线程与通信的总调度器&quot;">​</a></h2><p><img src="'+r+'" alt="Costmap2DROS 生命周期与更新线程"></p><h3 id="_3-1-构造入口和只读状态函数" tabindex="-1">3.1 构造入口和只读状态函数 <a class="header-anchor" href="#_3-1-构造入口和只读状态函数" aria-label="Permalink to &quot;3.1 构造入口和只读状态函数&quot;">​</a></h3><p>三个 <code>Costmap2DROS()</code> 构造入口分别支持独立节点、NodeOptions 组件和父／子命名空间嵌入。它们声明尺寸、频率、Frame、Footprint、插件、Filter、滚动窗口和未知空间等参数。析构函数本身为空，资源主要由 Lifecycle cleanup 与智能指针管理。</p><p><code>getName()</code>、<code>getGlobalFrameID()</code>、<code>getBaseFrameID()</code>、<code>getTransformTolerance()</code> 返回节点身份和 TF 配置；<code>getCostmap()</code>、<code>getLayeredCostmap()</code>、<code>getTfBuffer()</code> 暴露核心对象；<code>getRobotFootprint()</code>、<code>getUnpaddedRobotFootprint()</code>、<code>getRobotFootprintPolygon()</code> 返回不同表达形式；<code>getUseRadius()</code>、<code>getRobotRadius()</code> 描述机器人几何来源；<code>isCurrent()</code> 委托 LayeredCostmap 判断所有启用层是否及时。</p><p><code>on_rcl_preshutdown()</code> 主动调用 shutdown transition，防止进程退出时跳过生命周期收尾。</p><h3 id="_3-2-on-configure-建立整条链" tabindex="-1">3.2 on_configure() 建立整条链 <a class="header-anchor" href="#_3-2-on-configure-建立整条链" aria-label="Permalink to &quot;3.2 on_configure() 建立整条链&quot;">​</a></h3><p><code>getParameters()</code> 读取参数，解析默认插件类型，计算发布周期，并用 <code>makeFootprintFromString()</code> 判断使用 polygon 还是 radius。</p><p><code>on_configure()</code> 创建 <code>LayeredCostmap</code>，必要时按米制尺寸除以分辨率完成 resize；创建包外 TF Buffer、TransformListener 和定时器接口；用 pluginlib 加载 Layer 与 Filter，并在 master costmap 锁内调用 <code>Layer::initialize()</code>。</p><p>它还创建 Footprint 订阅／发布、<code>Costmap2DPublisher</code>、<code>ClearCostmapService</code>、互斥 CallbackGroup、SingleThreadedExecutor 和包外 <code>nav2_util::NodeThread</code>。输出是已配置但尚未周期更新的 Costmap 节点。</p><h3 id="_3-3-on-activate-到-on-cleanup" tabindex="-1">3.3 on_activate() 到 on_cleanup() <a class="header-anchor" href="#_3-3-on-activate-到-on-cleanup" aria-label="Permalink to &quot;3.3 on_activate() 到 on_cleanup()&quot;">​</a></h3><p><code>on_activate()</code> 激活 Costmap 与 Footprint Lifecycle Publisher，循环等待 <code>global_frame &lt;- robot_base_frame</code> TF，然后创建 <code>mapUpdateLoop()</code> 线程，调用 <code>start()</code> 激活各层，最后注册动态参数回调。</p><p><code>on_deactivate()</code> 先注销参数回调，调用 <code>stop()</code> 停用 Layer／Filter，再设置线程退出标志并 join，最后停用 Publisher。<code>on_cleanup()</code> 销毁 LayeredCostmap、TF、通信对象、清图服务和内部执行线程。<code>on_shutdown()</code> 只记录状态并返回成功。</p><h3 id="_3-4-start-、stop-、pause-、resume" tabindex="-1">3.4 start()、stop()、pause()、resume() <a class="header-anchor" href="#_3-4-start-、stop-、pause-、resume" aria-label="Permalink to &quot;3.4 start()、stop()、pause()、resume()&quot;">​</a></h3><p><code>start()</code> 在 stopped 状态下调用每个插件与 Filter 的 <code>activate()</code>，放开更新标志，并阻塞等待至少一个成功更新周期把 <code>initialized_</code> 设为 true。</p><p><code>stop()</code> 禁止更新、调用所有 <code>deactivate()</code>，再清除 initialized 并标记 stopped。<code>pause()</code> 只暂停融合，不取消订阅；<code>resume()</code> 重新允许更新，并等待一轮地图成功。这个差异决定恢复时是否需要重新订阅传感器。</p><p><code>resetLayers()</code> 清空 master costmap，再调用所有 Layer／Filter 的 <code>reset()</code>。清图 Service 的全图清除最终走到这里。</p><h3 id="_3-5-mapupdateloop-和-updatemap" tabindex="-1">3.5 mapUpdateLoop() 和 updateMap() <a class="header-anchor" href="#_3-5-mapupdateloop-和-updatemap" aria-label="Permalink to &quot;3.5 mapUpdateLoop() 和 updateMap()&quot;">​</a></h3><p><code>mapUpdateLoop(frequency)</code> 在独立线程中按 WallRate 运行。频率为零时直接退出。每周期在动态参数互斥量保护下调用 <code>updateMap()</code>，再读取 LayeredCostmap 的更新边界并按 <code>publish_cycle_</code> 调用发布器。系统时间回跳也会触发重新发布。</p><p><code>updateMap()</code> 先用 <code>getRobotPose()</code> 取得机器人在 global frame 下的位姿。成功后把 x、y、yaw 交给 <code>LayeredCostmap::updateMap()</code>，再把 padded Footprint 变换到当前姿态并发布。位姿不可用时本周期不改图。</p><p><code>getRobotPose()</code> 调用包外 <code>nav2_util::getCurrentPose()</code>；<code>transformPoseToGlobalFrame()</code> 对同 Frame 直接复制，否则调用包外 <code>transformPoseInTargetFrame()</code>。</p><h3 id="_3-6-footprint-回调和动态参数" tabindex="-1">3.6 Footprint 回调和动态参数 <a class="header-anchor" href="#_3-6-footprint-回调和动态参数" aria-label="Permalink to &quot;3.6 Footprint 回调和动态参数&quot;">​</a></h3><p><code>setRobotFootprintPolygon()</code> 把 Polygon 消息转为 Point 数组，再调用 <code>setRobotFootprint()</code>。后者保存未 padding 版本，调用 <code>padFootprint()</code> 得到运行版本，并通知 LayeredCostmap。<code>getOrientedFootprint()</code> 获取机器人位姿后旋转平移 padded Footprint。</p><p><code>dynamicParametersCallback()</code> 在更新线程共用互斥量内处理 radius、padding、TF 容差、发布频率、分辨率、原点、宽高、Footprint 字符串和 base frame。宽高非正或新 base frame 无 TF 时返回失败。涉及地图几何的变更会在未 size lock 时 resize 并立即 update。</p><h2 id="四、layeredcostmap-先算边界-再按顺序写代价" tabindex="-1">四、LayeredCostmap：先算边界，再按顺序写代价 <a class="header-anchor" href="#四、layeredcostmap-先算边界-再按顺序写代价" aria-label="Permalink to &quot;四、LayeredCostmap：先算边界，再按顺序写代价&quot;">​</a></h2><p><img src="'+i+'" alt="Layered Costmap 两阶段融合"></p><h3 id="_4-1-layer-是插件契约" tabindex="-1">4.1 Layer 是插件契约 <a class="header-anchor" href="#_4-1-layer-是插件契约" aria-label="Permalink to &quot;4.1 Layer 是插件契约&quot;">​</a></h3><p><code>Layer()</code> 初始化父地图、TF、名称和状态为空。<code>initialize()</code> 注入 LayeredCostmap、插件名、TF、LifecycleNode 与 CallbackGroup，然后调用虚函数 <code>onInitialize()</code>。</p><p>默认 <code>activate()</code>、<code>deactivate()</code>、<code>matchSize()</code>、<code>onFootprintChanged()</code> 和 <code>onInitialize()</code> 是空实现；析构为虚析构。派生类必须实现 <code>updateBounds()</code>、<code>updateCosts()</code>、<code>reset()</code> 与 <code>isClearable()</code>。</p><p><code>getFootprint()</code> 向父对象取 Footprint；<code>getName()</code>、<code>isCurrent()</code>、<code>isEnabled()</code> 返回插件状态。<code>declareParameter()</code> 两个重载记录局部参数并调用包外 <code>nav2_util::declare_parameter_if_not_declared()</code>；<code>hasParameter()</code> 检查完整名称；<code>getFullName()</code> 拼接 <code>插件名.参数名</code>。</p><h3 id="_4-2-costmaplayer-提供可写网格和四种合并策略" tabindex="-1">4.2 CostmapLayer 提供可写网格和四种合并策略 <a class="header-anchor" href="#_4-2-costmaplayer-提供可写网格和四种合并策略" aria-label="Permalink to &quot;4.2 CostmapLayer 提供可写网格和四种合并策略&quot;">​</a></h3><p><code>CostmapLayer()</code> 初始化 extra bounds；<code>isDiscretized()</code> 返回 true。<code>matchSize()</code> 把自身网格对齐 master。<code>touch()</code> 扩大世界坐标边界。</p><p><code>addExtraBounds()</code> 累积外部要求刷新的区域；<code>useExtraBounds()</code> 把它并入本轮边界后清空。清图 Service 借此保证被清区域会进入下一轮融合。</p><p><code>clearArea()</code> 按 invert 决定清窗口内部还是外部。<code>updateWithTrueOverwrite()</code> 连 <code>NO_INFORMATION</code> 也覆盖；<code>updateWithOverwrite()</code> 跳过未知；<code>updateWithMax()</code> 取更高代价；<code>updateWithAddition()</code> 相加并在内切障碍代价以下饱和。每个派生层选择哪种策略，直接决定它与前序层如何交互。</p><h3 id="_4-3-layeredcostmap-管理-primary-与-combined" tabindex="-1">4.3 LayeredCostmap 管理 primary 与 combined <a class="header-anchor" href="#_4-3-layeredcostmap-管理-primary-与-combined" aria-label="Permalink to &quot;4.3 LayeredCostmap 管理 primary 与 combined&quot;">​</a></h3><p>构造函数根据 <code>track_unknown</code> 设置背景值，维护 <code>primary_costmap_</code> 与 <code>combined_costmap_</code>。<code>addPlugin()</code> 和 <code>addFilter()</code> 在 master 锁内追加对象；析构清空两个容器。</p><p><code>resizeMap()</code> 同时调整 primary、combined 和全部已加载层。<code>isOutofBounds()</code> 检查机器人是否落在 combined 外。<code>setFootprint()</code> 计算内切／外接半径，并通知全部插件和 Filter。</p><p>Frame、Costmap、rolling、unknown、插件表、Filter 表、size lock、更新边界、初始化状态、Footprint 和两个半径的 getter 都只暴露现有状态，不启动计算。</p><h3 id="_4-4-updatemap-是包内最关键的数据流" tabindex="-1">4.4 updateMap() 是包内最关键的数据流 <a class="header-anchor" href="#_4-4-updatemap-是包内最关键的数据流" aria-label="Permalink to &quot;4.4 updateMap() 是包内最关键的数据流&quot;">​</a></h3><p>滚动窗口模式先调用两张 Costmap 的 <code>updateOrigin()</code>。随后所有 Layer 和 Filter 依次执行 <code>updateBounds()</code>，只允许扩大边界；缩小边界会告警。世界边界再由 <code>worldToMapEnforceBounds()</code> 转成 cell 窗口。</p><p>没有 Filter 时，combined 在窗口内 reset，插件按配置顺序直接 <code>updateCosts(combined)</code>。</p><p>存在 Filter 时，插件先写 primary；<code>copyWindow()</code> 把 primary 的窗口复制到 combined；Filter 再按顺序处理 combined。这样 Filter 结果不会成为下一轮普通插件的输入。</p><p><code>isCurrent()</code> 汇总所有启用 Layer／Filter 的 current；禁用层不拖累结果。<code>getBounds()</code> 让 Publisher 知道本轮变化窗口。</p><h2 id="五、observationbuffer-把异步传感器消息变成可融合快照" tabindex="-1">五、ObservationBuffer：把异步传感器消息变成可融合快照 <a class="header-anchor" href="#五、observationbuffer-把异步传感器消息变成可融合快照" aria-label="Permalink to &quot;五、ObservationBuffer：把异步传感器消息变成可融合快照&quot;">​</a></h2><h3 id="_5-1-observation-的数据语义" tabindex="-1">5.1 Observation 的数据语义 <a class="header-anchor" href="#_5-1-observation-的数据语义" aria-label="Permalink to &quot;5.1 Observation 的数据语义&quot;">​</a></h3><p><code>Observation()</code> 默认创建空点云和零原点。其余构造重载接收 sensor origin、PointCloud2，以及 obstacle／raytrace 的最大最小量程。析构由共享点云和标准成员自动完成。</p><p>一个 Observation 不是原始 Topic 消息的别名，而是已经变换到 global frame、过滤高度、附带清除与标记量程的融合输入。</p><h3 id="_5-2-buffercloud-和缓存时效" tabindex="-1">5.2 bufferCloud() 和缓存时效 <a class="header-anchor" href="#_5-2-buffercloud-和缓存时效" aria-label="Permalink to &quot;5.2 bufferCloud() 和缓存时效&quot;">​</a></h3><p><code>ObservationBuffer()</code> 保存 Topic 名、保留时间、期望更新率、高度、量程、Frame、TF Buffer 与容差。<code>bufferCloud()</code> 创建新 Observation，用 TF 变换 sensor origin 和整片 PointCloud2，过滤高度外点，更新时间并清理旧记录。TF 异常会删除刚创建的空记录。</p><p><code>getObservations()</code> 先调用 <code>purgeStaleObservations()</code>，再复制有效记录。保留时间为零时只留最新一帧；否则按消息时间删除超期尾部。</p><p><code>isCurrent()</code> 用当前时间减 <code>last_updated_</code> 与期望周期比较；期望周期为零表示永远 current。<code>resetLastUpdated()</code> 在重新激活订阅时恢复时效基线。<code>lock()</code> 与 <code>unlock()</code> 让 ObstacleLayer 在复制缓存时显式保护列表。</p><h2 id="六、staticlayer-把-occupancygrid-变成-nav2-代价值" tabindex="-1">六、StaticLayer：把 OccupancyGrid 变成 Nav2 代价值 <a class="header-anchor" href="#六、staticlayer-把-occupancygrid-变成-nav2-代价值" aria-label="Permalink to &quot;六、StaticLayer：把 OccupancyGrid 变成 Nav2 代价值&quot;">​</a></h2><h3 id="_6-1-初始化与地图回调" tabindex="-1">6.1 初始化与地图回调 <a class="header-anchor" href="#_6-1-初始化与地图回调" aria-label="Permalink to &quot;6.1 初始化与地图回调&quot;">​</a></h3><p><code>StaticLayer()</code> 初始化延迟地图缓冲；析构不增加资源动作。<code>onInitialize()</code> 调用 <code>getParameters()</code>，按 transient local 配置订阅 map，按需订阅 <code>_updates</code>。</p><p><code>getParameters()</code> 读取 enabled、更新订阅、Footprint 清除、Topic、unknown、lethal threshold、trinary、maximum 和 TF 容差，并注册 <code>dynamicParametersCallback()</code>。</p><p><code>incomingMap()</code> 先调用包外 <code>nav2_util::validateMsg()</code>。首张图直接 <code>processMap()</code>；后续整图先存入 <code>map_buffer_</code>，由更新线程消费，避免订阅线程与融合线程同时重建数组。<code>incomingUpdate()</code> 校验窗口和 Frame，再只改对应区域。</p><h3 id="_6-2-数值解释、尺寸与融合" tabindex="-1">6.2 数值解释、尺寸与融合 <a class="header-anchor" href="#_6-2-数值解释、尺寸与融合" aria-label="Permalink to &quot;6.2 数值解释、尺寸与融合&quot;">​</a></h3><p><code>interpretValue()</code> 把 unknown 映射为未知或空闲，把阈值以上映射为致命障碍；trinary 模式把中间值当空闲，否则线性缩放。</p><p><code>processMap()</code> 在非 rolling 且几何变化时 resize 整个 LayeredCostmap；rolling 模式只调整本层。它遍历消息数据写入本层，标记整图更新并设置 current。</p><p><code>matchSize()</code> 只在非 rolling 模式对齐 master。<code>updateBounds()</code> 消费延迟整图、extra bounds 和地图更新矩形；<code>updateFootprint()</code> 在启用时把机器人多边形纳入边界。</p><p><code>updateCosts()</code> 可先在本层把 Footprint 内部清为空闲。非 rolling 模式选择 true overwrite 或 max；rolling 模式逐 cell 通过 TF 把 master 坐标投到 static map Frame 后读取。<code>reset()</code> 强制下一轮重刷；<code>activate()</code> 为空；<code>deactivate()</code> 注销动态参数处理器；<code>isClearable()</code> 返回 false。</p><p><code>dynamicParametersCallback()</code> 可更新 TF 容差、enabled 和 Footprint 清除。源码对 map Topic、QoS 和 updates 参数只告警，却最终仍返回 successful；并且两个连续 <code>PARAMETER_BOOL</code> 分支使 Footprint 清除分支在当前结构中不可达，这是阅读本地版本时必须注意的实现边界。</p><h2 id="七、obstaclelayer-与-voxellayer-标记障碍-也沿射线清空旧障碍" tabindex="-1">七、ObstacleLayer 与 VoxelLayer：标记障碍，也沿射线清空旧障碍 <a class="header-anchor" href="#七、obstaclelayer-与-voxellayer-标记障碍-也沿射线清空旧障碍" aria-label="Permalink to &quot;七、ObstacleLayer 与 VoxelLayer：标记障碍，也沿射线清空旧障碍&quot;">​</a></h2><p><img src="'+n+'" alt="Static、Obstacle、Voxel 与 Range 输入链"></p><h3 id="_7-1-obstaclelayer-初始化传感器" tabindex="-1">7.1 ObstacleLayer 初始化传感器 <a class="header-anchor" href="#_7-1-obstaclelayer-初始化传感器" aria-label="Permalink to &quot;7.1 ObstacleLayer 初始化传感器&quot;">​</a></h3><p><code>ObstacleLayer()</code> 内联构造设置 combination method；析构注销参数回调并销毁 MessageFilter。<code>onInitialize()</code> 读取 observation_sources，为每个源声明 Topic、类型、高度、保留时间、期望更新率、marking、clearing 和量程。</p><p>LaserScan 源创建包外 <code>message_filters::Subscriber</code> 与 <code>tf2_ros::MessageFilter</code>；PointCloud2 源同样等待 TF。每个源对应一个 <code>ObservationBuffer</code>，再按 marking／clearing 放入不同容器。</p><h3 id="_7-2-三个消息回调" tabindex="-1">7.2 三个消息回调 <a class="header-anchor" href="#_7-2-三个消息回调" aria-label="Permalink to &quot;7.2 三个消息回调&quot;">​</a></h3><p><code>laserScanCallback()</code> 用 <code>LaserProjection::transformLaserScanToPointCloud()</code> 直接得到 global-frame 点云；<code>laserScanValidInfCallback()</code> 先把正无穷替换成 <code>range_max - epsilon</code>，使清除射线能覆盖无返回方向；两者最后调用 Buffer 的 <code>bufferCloud()</code>。</p><p><code>pointCloud2Callback()</code> 直接把 PointCloud2 交给 Buffer。TF 等待和消息丢弃由包外 MessageFilter 处理。</p><h3 id="_7-3-updatebounds-与-updatecosts" tabindex="-1">7.3 updateBounds() 与 updateCosts() <a class="header-anchor" href="#_7-3-updatebounds-与-updatecosts" aria-label="Permalink to &quot;7.3 updateBounds() 与 updateCosts()&quot;">​</a></h3><p><code>getMarkingObservations()</code>、<code>getClearingObservations()</code> 从各 Buffer 复制数据，并把 current 汇总。静态观测由 <code>addStaticObservation()</code> 加入 marking／clearing 容器，<code>clearStaticObservations()</code> 按用途清空。</p><p><code>updateBounds()</code> 在 rolling 模式移动自身原点，取得 clearing 与 marking 观测。<code>raytraceFreespace()</code> 从 sensor origin 向每个点发 Bresenham 射线清为空闲，<code>updateRaytraceBounds()</code> 把量程裁剪后的射线端点计入边界。标记阶段过滤高度和距离，把命中 cell 写成致命障碍。<code>updateFootprint()</code> 可把机器人轮廓内区域清空。</p><p><code>updateCosts()</code> 根据 <code>combination_method_</code> 选择 overwrite、max 或“不参与合并”。<code>activate()</code> 重新订阅并 reset Buffer 时间；<code>deactivate()</code> 取消订阅；<code>reset()</code> 清自身地图后重新激活；<code>resetBuffersLastUpdated()</code> 只更新时间基线；<code>isClearable()</code> 返回 true。</p><p><code>dynamicParametersCallback()</code> 更新 enabled、Footprint 清除、障碍高度、量程与 combination method。观测源拓扑不是运行时重建对象。</p><h3 id="_7-4-voxellayer-的三维差异" tabindex="-1">7.4 VoxelLayer 的三维差异 <a class="header-anchor" href="#_7-4-voxellayer-的三维差异" aria-label="Permalink to &quot;7.4 VoxelLayer 的三维差异&quot;">​</a></h3><p><code>VoxelLayer()</code> 初始化 Z 方向参数；<code>onInitialize()</code> 先调用 ObstacleLayer，再读取 z voxels、origin z、z resolution、unknown／mark threshold 与发布开关。<code>matchSize()</code> 同步二维数组并 resize VoxelGrid；<code>reset()</code> 和 <code>resetMaps()</code> 同时清二维与三维数据。</p><p><code>worldToMap3DFloat()</code> 返回浮点 voxel 坐标；<code>worldToMap3D()</code> 返回离散索引；<code>mapToWorld3D()</code> 做逆变换；<code>dist()</code> 计算三维距离；<code>getSizeInMetersZ()</code> 返回 Z 高度；<code>isDiscretized()</code> 与 <code>isClearable()</code> 均返回 true。</p><p><code>updateBounds()</code> 从 Observation 中筛点并调用包外 <code>markVoxelInMap()</code>。一个二维列达到 <code>mark_threshold_</code> 后，二维 costmap 才写致命障碍。启用发布时，它把压缩 voxel 数据发成 <code>nav2_msgs::msg::VoxelGrid</code>。</p><p><code>raytraceFreespace()</code> 把射线裁到三维网格边界，调用包外 <code>clearVoxelLineInMap()</code> 同时修改 VoxelGrid 和二维数组，并可发布 clearing endpoints。<code>updateOrigin()</code> 同步平移二维 costmap 和三维压缩数组。</p><p><code>dynamicParametersCallback()</code> 更新 Z 尺寸和阈值，必要时 <code>matchSize()</code>；<code>publish_voxel_map</code> 被提示为非动态参数，但当前代码使用 continue 后仍会让整批结果成功。</p><h2 id="八、rangesensorlayer-把扇形声呐观测融合成概率" tabindex="-1">八、RangeSensorLayer：把扇形声呐观测融合成概率 <a class="header-anchor" href="#八、rangesensorlayer-把扇形声呐观测融合成概率" aria-label="Permalink to &quot;八、RangeSensorLayer：把扇形声呐观测融合成概率&quot;">​</a></h2><h3 id="_8-1-回调缓冲与消息分类" tabindex="-1">8.1 回调缓冲与消息分类 <a class="header-anchor" href="#_8-1-回调缓冲与消息分类" aria-label="Permalink to &quot;8.1 回调缓冲与消息分类&quot;">​</a></h3><p><code>RangeSensorLayer()</code> 构造为空。<code>onInitialize()</code> 读取 Topic、阈值、clear-on-max、cone inflation、超时和 input sensor type，为每个 Topic 创建 SensorDataQoS 订阅。</p><p><code>bufferIncomingRangeMsg()</code> 只把消息复制进受锁列表。<code>updateCostmap()</code> 无参重载在更新线程交换缓冲，再调用绑定的处理函数。这样 ROS 回调不直接遍历 Costmap。</p><p><code>processRangeMsg()</code> 根据 <code>min_range == max_range</code> 分派固定或可变量程传感器。<code>processFixedRangeMsg()</code> 只接受正负无穷语义；<code>processVariableRangeMsg()</code> 丢弃量程外数据，并判断是否清空整个锥体。</p><h3 id="_8-2-概率模型与栅格更新" tabindex="-1">8.2 概率模型与栅格更新 <a class="header-anchor" href="#_8-2-概率模型与栅格更新" aria-label="Permalink to &quot;8.2 概率模型与栅格更新&quot;">​</a></h3><p><code>gamma()</code> 描述角度可信度，<code>delta()</code> 描述距离边界，<code>sensor_model()</code> 合成占用概率。<code>get_deltas()</code> 计算沿射线移动一个栅格所需的 x、y 增量。</p><p>带消息的 <code>updateCostmap()</code> 用包外 TF 得到 sensor origin 和目标点，计算锥形三角形边界，使用 <code>area()</code> 与 <code>orient2d()</code> 判断 cell 是否落在膨胀后的锥体内，再调用 <code>update_cell()</code>。</p><p><code>update_cell()</code> 用 <code>to_prob()</code> 把当前 cost 还原为概率，通过贝叶斯形式合成 sensor 概率，再用 <code>to_cost()</code> 写回。<code>resetRange()</code> 清本轮边界；<code>updateBounds()</code> 处理缓冲、并入边界并检查无数据超时；<code>updateCosts()</code> 按 clear／mark threshold 把概率层翻译为空闲或致命障碍。</p><p><code>reset()</code> 清图并重启；<code>activate()</code> 与 <code>deactivate()</code> 都清消息缓冲；<code>isClearable()</code> 返回 true。</p><h2 id="九、inflationlayer-与-denoiselayer-一个扩风险-一个删孤点" tabindex="-1">九、InflationLayer 与 DenoiseLayer：一个扩风险，一个删孤点 <a class="header-anchor" href="#九、inflationlayer-与-denoiselayer-一个扩风险-一个删孤点" aria-label="Permalink to &quot;九、InflationLayer 与 DenoiseLayer：一个扩风险，一个删孤点&quot;">​</a></h2><p><img src="'+l+'" alt="Inflation 与 Denoise 算法"></p><h3 id="_9-1-inflationlayer-的缓存和波前" tabindex="-1">9.1 InflationLayer 的缓存和波前 <a class="header-anchor" href="#_9-1-inflationlayer-的缓存和波前" aria-label="Permalink to &quot;9.1 InflationLayer 的缓存和波前&quot;">​</a></h3><p><code>InflationLayer()</code> 初始化半径、缩放、缓存和更新边界，并创建独立递归锁；析构注销回调并释放锁。<code>CellData</code> 保存当前 cell、坐标和最近障碍源坐标。</p><p><code>computeCost()</code> 接收栅格距离 <code>distance</code>，在障碍源返回致命代价，在机器人内切半径内返回内切障碍代价，外部按 <code>exp(-factor * distance)</code> 衰减。<code>cellDistance()</code> 把米转 cell；<code>distanceLookup()</code> 与 <code>costLookup()</code> 查预计算表；<code>getMutex()</code> 返回本层锁；<code>isClearable()</code> 返回 false；内联 <code>reset()</code> 把 current 置 false。</p><p><code>onInitialize()</code> 读取 enabled、inflation radius、scaling factor 和 unknown 策略。<code>matchSize()</code> 读取 master 分辨率、重算 cell 半径、缓存与 seen 数组。<code>onFootprintChanged()</code> 更新内切半径并强制全图重新膨胀。</p><p><code>computeCaches()</code> 生成距离矩阵与 cost 表；<code>generateIntegerDistances()</code> 把相同平方距离分到同一个整数层级；<code>enqueue()</code> 只把半径内且未访问的邻居放进对应距离桶。</p><p><code>updateBounds()</code> 把本轮和上一轮边界扩展 inflation radius；需要 reinflation 时要求整图更新。<code>updateCosts()</code> 先收集致命障碍与可选未知源，再按距离桶从近到远传播，取原代价与膨胀代价的最大值。</p><p><code>dynamicParametersCallback()</code> 更新半径、缩放、unknown 策略和 enabled，并按需重建缓存、触发 reinflation。</p><h3 id="_9-2-denoiselayer-的两条路径" tabindex="-1">9.2 DenoiseLayer 的两条路径 <a class="header-anchor" href="#_9-2-denoiselayer-的两条路径" aria-label="Permalink to &quot;9.2 DenoiseLayer 的两条路径&quot;">​</a></h3><p><code>DenoiseLayer::onInitialize()</code> 读取 enabled、最小连通域和 4／8 邻域；<code>reset()</code> 让 current 失效；<code>isClearable()</code> 返回 false；<code>updateBounds()</code> 不扩大区域。</p><p><code>updateCosts()</code> 不复制图像，而是用 <code>Image&lt;uint8_t&gt;</code> 包装 master 更新窗口。<code>denoise()</code> 在最小组为二时走 <code>removeSinglePixels()</code>，更大时走 <code>removeGroups()</code>；<code>isBackground()</code> 根据致命、内切和 unknown 策略判断背景。</p><p><code>removeSinglePixels()</code> 调用 <code>dilate()</code> 生成邻域最大值图，再用 <code>Image::convert()</code> 清除没有障碍邻居的孤点。<code>removeGroups()</code> 调用 GroupsRemover，对连通域标号后按面积删除小组。</p><h3 id="_9-3-image-与连通域模板函数" tabindex="-1">9.3 Image 与连通域模板函数 <a class="header-anchor" href="#_9-3-image-与连通域模板函数" aria-label="Permalink to &quot;9.3 Image 与连通域模板函数&quot;">​</a></h3><p><code>Image</code> 的默认／缓冲／拷贝／移动构造都只管理视图，不拥有外部缓冲区。<code>rows()</code>、<code>columns()</code>、<code>empty()</code>、<code>step()</code> 返回几何；<code>row()</code> 两个重载定位行；<code>forEach()</code> 两个重载遍历像素；<code>convert()</code> 对等尺寸图执行逐像素转换。</p><p><code>MemoryBuffer::get()</code> 按需扩容，<code>allocate()</code> 重分配，<code>reset()</code> 释放。<code>dilate()</code> 根据连接类型创建 shape 并调用 <code>morphologyOperation()</code>；<code>probeRows()</code> 负责一维滑窗；<code>createShape()</code> 生成 4／8 邻域结构元素；<code>histogram()</code> 生成截断直方图。</p><p>边界策略 <code>DoNothing::up()/down()</code> 直接解引用；<code>ReplaceToZero::up()/down()/replaceOutOfBounds()</code> 对越界返回零。<code>Window</code> 构造与 <code>a()/b()/c()/d()/e()/anchor()/next()</code> 提供前向扫描邻域。<code>dropConst()</code>、<code>makeSafeWindow()</code>、<code>makeUnsafeWindow()</code> 负责创建窗口。</p><p><code>EquivalenceLabelTrees::reset()</code>、<code>makeLabel()</code>、<code>unionTrees()</code>、<code>getLabels()</code>、<code>maxLabels()</code>、<code>findRoot()</code>、<code>setRoot()</code> 构成并查集。两个 <code>ProcessPixel::pass()</code> 分别执行 8 邻域与 4 邻域标签决策。</p><p><code>connectedComponentsImpl()</code> 执行扫描、等价分析和重标号；<code>connectedComponents()</code> 分配标签图并调用实现。<code>GroupsRemover()</code> 初始化 16 位标签树；<code>removeGroups()</code> 按运行参数选择连接方式；<code>removeGroupsPickLabelType()</code> 在标签溢出时升级 32 位；<code>tryRemoveGroupsWithLabelType()</code> 管理异常策略；<code>removeGroupsImpl()</code> 统计每个标签面积并清除小组。<code>LabelOverflow</code> 用于报告标签容量不足。</p><h2 id="十、costmap-filters-mask-不只是禁行区" tabindex="-1">十、Costmap Filters：Mask 不只是禁行区 <a class="header-anchor" href="#十、costmap-filters-mask-不只是禁行区" aria-label="Permalink to &quot;十、Costmap Filters：Mask 不只是禁行区&quot;">​</a></h2><p><img src="'+s+'" alt="Filter、发布、碰撞检查与清图接口"></p><h3 id="_10-1-costmapfilter-基类" tabindex="-1">10.1 CostmapFilter 基类 <a class="header-anchor" href="#_10-1-costmapfilter-基类" aria-label="Permalink to &quot;10.1 CostmapFilter 基类&quot;">​</a></h3><p><code>CostmapFilter()</code> 创建独立锁；析构释放锁。<code>onInitialize()</code> 声明 enabled、Filter Info Topic 和 TF 容差，并创建 <code>toggle_filter</code> Service。</p><p><code>activate()</code> 调用派生 <code>initializeFilter()</code>；<code>deactivate()</code> 调用 <code>resetFilter()</code>；<code>reset()</code> 先重置再初始化。<code>updateBounds()</code> 缓存机器人 Pose2D；<code>updateCosts()</code> 把 master 窗口与位姿交给派生 <code>process()</code>。</p><p><code>enableCallback()</code> 修改 enabled 并回复 SetBool。<code>transformPose()</code> 用包外 TF 把机器人位置转换到 Mask Frame；<code>worldToMask()</code> 把世界坐标转 Mask 索引；<code>getMaskData()</code> 读取 OccupancyGrid；<code>getMutex()</code> 返回 Filter 锁；<code>isClearable()</code> 返回 false。</p><h3 id="_10-2-keepoutfilter" tabindex="-1">10.2 KeepoutFilter <a class="header-anchor" href="#_10-2-keepoutfilter" aria-label="Permalink to &quot;10.2 KeepoutFilter&quot;">​</a></h3><p><code>KeepoutFilter()</code> 初始化订阅与 Mask Costmap。<code>initializeFilter()</code> 订阅 CostmapFilterInfo；<code>filterInfoCallback()</code> 校验 base／multiplier 并改订阅 Mask Topic；<code>maskCallback()</code> 把 OccupancyGrid 构造成 Costmap2D。</p><p><code>updateBounds()</code> 在 Mask 更新时扩大刷新范围。<code>process()</code> 求 master 与 Mask 的重叠区，必要时用 TF 投影，再把 Mask 中更高且非 unknown 的代价写入 master。<code>resetFilter()</code> 取消两个订阅；<code>isActive()</code> 以 Mask 是否到达判断可用。</p><h3 id="_10-3-speedfilter" tabindex="-1">10.3 SpeedFilter <a class="header-anchor" href="#_10-3-speedfilter" aria-label="Permalink to &quot;10.3 SpeedFilter&quot;">​</a></h3><p><code>SpeedFilter()</code> 初始化速度状态。<code>initializeFilter()</code> 订阅 Filter Info、创建 SpeedLimit Lifecycle Publisher 并重置换算参数。<code>filterInfoCallback()</code> 读取绝对／百分比模式、base、multiplier 和 Mask Topic；<code>maskCallback()</code> 缓存 Mask 与 Frame。</p><p><code>process()</code> 把机器人位置转换到 Mask cell，用 <code>base + cell * multiplier</code> 计算限制。数值变化时发布 SpeedLimit；unknown cell 不更新；越界也不主动发布无限制。<code>resetFilter()</code> 取消订阅并销毁 Publisher；<code>isActive()</code> 检查 Mask。</p><h3 id="_10-4-binaryfilter" tabindex="-1">10.4 BinaryFilter <a class="header-anchor" href="#_10-4-binaryfilter" aria-label="Permalink to &quot;10.4 BinaryFilter&quot;">​</a></h3><p><code>BinaryFilter()</code> 保存默认状态。<code>initializeFilter()</code> 读取 Topic、default state 和 flip threshold，创建 Bool Publisher 并调用 <code>changeState()</code> 发布初值。</p><p><code>filterInfoCallback()</code> 只接受 Binary 类型并订阅 Mask；<code>maskCallback()</code> 缓存消息；<code>process()</code> 读取机器人所在 Mask cell，经 base／multiplier 换算后与阈值比较，决定是否翻转默认状态。机器人越界时恢复默认，unknown 时保持当前状态。</p><p><code>changeState()</code> 更新成员并发布 Bool。<code>resetFilter()</code> 恢复默认状态、取消订阅和 Publisher；<code>isActive()</code> 判断 Mask 是否存在。</p><h2 id="十一、footprint-与碰撞检查-代价值必须结合机器人形状" tabindex="-1">十一、Footprint 与碰撞检查：代价值必须结合机器人形状 <a class="header-anchor" href="#十一、footprint-与碰撞检查-代价值必须结合机器人形状" aria-label="Permalink to &quot;十一、Footprint 与碰撞检查：代价值必须结合机器人形状&quot;">​</a></h2><h3 id="_11-1-footprint-自由函数" tabindex="-1">11.1 Footprint 自由函数 <a class="header-anchor" href="#_11-1-footprint-自由函数" aria-label="Permalink to &quot;11.1 Footprint 自由函数&quot;">​</a></h3><p><code>calculateMinAndMaxDistances()</code> 计算原点到所有顶点和边的最小／最大距离，分别成为内切与外接半径。<code>toPoint()</code>、<code>toPoint32()</code>、<code>toPolygon()</code>、<code>toPointVector()</code> 在内部 Point 数组和 ROS 消息之间转换。</p><p>两个 <code>transformFootprint()</code> 重载都执行二维旋转平移，一个输出 Point 数组，一个输出 PolygonStamped。<code>padFootprint()</code> 沿顶点坐标符号扩大外形。<code>makeFootprintFromRadius()</code> 用十六个采样点近似圆。</p><p><code>parseVVF()</code> 是字符串二维浮点数组解析器；<code>makeFootprintFromString()</code> 要求至少三个二维点，任何深度、括号或元素维度错误都会返回 false。</p><h3 id="_11-2-footprintcollisionchecker" tabindex="-1">11.2 FootprintCollisionChecker <a class="header-anchor" href="#_11-2-footprintcollisionchecker" aria-label="Permalink to &quot;11.2 FootprintCollisionChecker&quot;">​</a></h3><p>两个构造函数分别创建空检查器或绑定 Costmap；<code>setCostmap()</code> 可后置替换，<code>getCostmap()</code> 返回当前对象。</p><p><code>footprintCostAtPose()</code> 先变换 Footprint，再调用 <code>footprintCost()</code>。后者把顶点投到地图，逐边调用 <code>lineCost()</code>；<code>lineCost()</code> 用 Bresenham 遍历并调用 <code>pointCost()</code>。任何顶点越界返回负值；致命或未知代价按当前逻辑直接成为碰撞分数。<code>worldToMap()</code> 委托 Costmap。</p><h3 id="_11-3-topic-客户端" tabindex="-1">11.3 Topic 客户端 <a class="header-anchor" href="#_11-3-topic-客户端" aria-label="Permalink to &quot;11.3 Topic 客户端&quot;">​</a></h3><p><code>CostmapSubscriber</code> 两个构造函数支持普通 Node 与 LifecycleNode，订阅 raw Costmap。<code>costmapCallback()</code> 缓存消息并标记待转换；<code>toCostmap2D()</code> 根据 metadata 构造本地数组；<code>getCostmap()</code> 在锁内按需转换；析构为默认。</p><p><code>FootprintSubscriber</code> 两个构造函数同样支持两类 Node。<code>footprint_callback()</code> 缓存 PolygonStamped；<code>getFootprintRaw()</code> 返回原消息转换后的 Point 数组；<code>getFootprintInRobotFrame()</code> 调用包外 TF 把 Polygon 变到 robot frame；析构为默认。</p><p><code>CostmapTopicCollisionChecker()</code> 组合两个 Subscriber。<code>getFootprint()</code> 根据请求选择 radius 或最新 polygon，并变换到目标姿态；<code>scorePose()</code> 创建 FootprintCollisionChecker 计算分数；<code>isCollisionFree()</code> 把非负且低于致命阈值视为无碰撞。</p><h2 id="十二、清图-service、数学工具和可执行入口" tabindex="-1">十二、清图 Service、数学工具和可执行入口 <a class="header-anchor" href="#十二、清图-service、数学工具和可执行入口" aria-label="Permalink to &quot;十二、清图 Service、数学工具和可执行入口&quot;">​</a></h2><h3 id="_12-1-clearcostmapservice" tabindex="-1">12.1 ClearCostmapService <a class="header-anchor" href="#_12-1-clearcostmapservice" aria-label="Permalink to &quot;12.1 ClearCostmapService&quot;">​</a></h3><p>构造函数创建 clear-except、clear-around、clear-entirely 三个 Service；析构销毁 Service。</p><p>三个回调分别把 reset distance 和 invert 语义传给 <code>clearRegion()</code>，或调用 <code>clearEntirely()</code>。<code>getPosition()</code> 通过 Costmap2DROS 获取机器人位姿。</p><p><code>clearRegion()</code> 只处理 <code>isClearable()</code> 为 true 的普通插件，不处理 Filter。<code>clearLayerRegion()</code> 把机器人周围世界窗口转成 cell，调用 <code>clearArea()</code>，再用 <code>addExtraBounds()</code> 强制下一轮刷新整层。<code>clearEntirely()</code> 在 master 锁内调用 <code>resetLayers()</code>。</p><h3 id="_12-2-数学工具" tabindex="-1">12.2 数学工具 <a class="header-anchor" href="#_12-2-数学工具" aria-label="Permalink to &quot;12.2 数学工具&quot;">​</a></h3><p>全局 <code>sign()</code> 返回正负一，<code>sign0()</code> 在零输入时返回零，<code>distance()</code> 计算二维欧氏距离。<code>distanceToLine()</code> 把点投影到有限线段，投影超出端点时退化为端点距离。这些函数被 Footprint 与 Range 几何复用。</p><h3 id="_12-3-三个可执行入口" tabindex="-1">12.3 三个可执行入口 <a class="header-anchor" href="#_12-3-三个可执行入口" aria-label="Permalink to &quot;12.3 三个可执行入口&quot;">​</a></h3><p><code>costmap_2d_node::main()</code> 初始化 ROS 2，创建独立 <code>Costmap2DROS(&quot;costmap&quot;)</code>，spin 后 shutdown。</p><p>Voxel Marker 的 <code>voxelCallback()</code> 遍历压缩 VoxelGrid，只把 MARKED voxel 转成 CubeList Marker；其 <code>main()</code> 创建订阅与 Marker Publisher。</p><p>Voxel Cloud 的 <code>mapToWorld3D()</code> 把 voxel 索引变成中心世界坐标；<code>pointCloud2Helper()</code> 填充 XYZRGB PointCloud2；<code>voxelCallback()</code> 分离 MARKED 与 UNKNOWN 并发布两片点云；<code>main()</code> 建立节点、两个 Publisher 和 VoxelGrid Subscription。</p><h2 id="十三、把完整链路压缩成一次更新周期" tabindex="-1">十三、把完整链路压缩成一次更新周期 <a class="header-anchor" href="#十三、把完整链路压缩成一次更新周期" aria-label="Permalink to &quot;十三、把完整链路压缩成一次更新周期&quot;">​</a></h2><h3 id="_13-1-数据进入" tabindex="-1">13.1 数据进入 <a class="header-anchor" href="#_13-1-数据进入" aria-label="Permalink to &quot;13.1 数据进入&quot;">​</a></h3><p>地图和传感器回调只完成校验、TF 等待、消息转换和缓存。它们不直接驱动 Planner，也不直接发布 master costmap。</p><h3 id="_13-2-边界汇总" tabindex="-1">13.2 边界汇总 <a class="header-anchor" href="#_13-2-边界汇总" aria-label="Permalink to &quot;13.2 边界汇总&quot;">​</a></h3><p>更新线程取得机器人位姿，LayeredCostmap 调用所有 <code>updateBounds()</code>。滚动窗口、传感器射线、地图更新、Footprint 和 extra bounds 在这里汇成最小刷新矩形。</p><h3 id="_13-3-代价融合" tabindex="-1">13.3 代价融合 <a class="header-anchor" href="#_13-3-代价融合" aria-label="Permalink to &quot;13.3 代价融合&quot;">​</a></h3><p>普通 Layer 按配置顺序执行 <code>updateCosts()</code>。Static 给出底图，Obstacle／Voxel／Range 写动态信息，Denoise 可删孤点，Inflation 扩展安全边界。存在 Filter 时，普通层先写 primary，Filter 再处理 combined。</p><h3 id="_13-4-输出与消费" tabindex="-1">13.4 输出与消费 <a class="header-anchor" href="#_13-4-输出与消费" aria-label="Permalink to &quot;13.4 输出与消费&quot;">​</a></h3><p>Publisher 把同一张 combined costmap 输出为 raw Costmap、OccupancyGrid 或局部 Update。Planner 与 Controller 从 Costmap2DROS 读取它；客户端碰撞检查器通过 Topic 复制一份本地 Costmap；SpeedFilter 的限制则通过独立 Topic 进入 Controller Server。</p><h2 id="十四、阅读当前源码时最值得记住的边界" tabindex="-1">十四、阅读当前源码时最值得记住的边界 <a class="header-anchor" href="#十四、阅读当前源码时最值得记住的边界" aria-label="Permalink to &quot;十四、阅读当前源码时最值得记住的边界&quot;">​</a></h2><h3 id="_14-1-current-不等于收到过一次数据" tabindex="-1">14.1 current 不等于收到过一次数据 <a class="header-anchor" href="#_14-1-current-不等于收到过一次数据" aria-label="Permalink to &quot;14.1 current 不等于收到过一次数据&quot;">​</a></h3><p>ObservationBuffer 的 current 与期望更新率有关，LayeredCostmap 又会忽略 disabled 层。排障时必须逐层检查 enabled、expected update rate、TF 和 Topic，而不能只看 Costmap Topic 是否存在。</p><h3 id="_14-2-更新频率与发布频率是两套时钟" tabindex="-1">14.2 更新频率与发布频率是两套时钟 <a class="header-anchor" href="#_14-2-更新频率与发布频率是两套时钟" aria-label="Permalink to &quot;14.2 更新频率与发布频率是两套时钟&quot;">​</a></h3><p><code>update_frequency</code> 决定融合线程，<code>publish_frequency</code> 只决定对外发送。地图内部已经更新，不代表 RViz 立即看到；发布频率为零时仍可被 Planner／Controller 直接读取。</p><h3 id="_14-3-清图不是把所有层永久写成空闲" tabindex="-1">14.3 清图不是把所有层永久写成空闲 <a class="header-anchor" href="#_14-3-清图不是把所有层永久写成空闲" aria-label="Permalink to &quot;14.3 清图不是把所有层永久写成空闲&quot;">​</a></h3><p>可清层被置为 unknown 后，下一轮传感器和静态输入可能再次写回。Static、Inflation、Denoise 和 Filter 的 <code>isClearable()</code> 为 false，清图行为天然是分层的。</p><h3 id="_14-4-filter-与普通-layer-不在同一反馈路径" tabindex="-1">14.4 Filter 与普通 Layer 不在同一反馈路径 <a class="header-anchor" href="#_14-4-filter-与普通-layer-不在同一反馈路径" aria-label="Permalink to &quot;14.4 Filter 与普通 Layer 不在同一反馈路径&quot;">​</a></h3><p>有 Filter 时，primary 保留普通插件结果，combined 承载 Filter 后结果。这防止禁行或速度语义反向污染普通障碍图，但也意味着查看 Layer 内部数组与查看最终 Topic 可能得到不同结果。</p><h3 id="_14-5-动态参数回调不全是严格拒绝" tabindex="-1">14.5 动态参数回调不全是严格拒绝 <a class="header-anchor" href="#_14-5-动态参数回调不全是严格拒绝" aria-label="Permalink to &quot;14.5 动态参数回调不全是严格拒绝&quot;">​</a></h3><p>若回调只是打印“非动态参数”却仍返回 successful，参数存储可能变化而运行对象不重建。StaticLayer 的重复 bool 分支和 VoxelLayer 的 continue 都属于本地版本可见的实现边界。调参后必须用实际 Topic、Layer 状态和地图变化验证，不能只看 <code>ros2 param set</code> 返回成功。</p><p><code>nav2_costmap_2d</code> 的本质不是“画一张障碍图”，而是一个带 Lifecycle、TF、异步缓存、插件顺序、时效判断、局部更新、语义 Filter 和多消费者接口的实时数据融合系统。真正理解它之后，Costmap 问题就不再是“地图为什么不对”，而可以准确落到某个输入回调、某个 Frame、某个 Layer 的 bounds、某种合并策略，或某个输出节拍。</p>',204)])])}const C=o(p,[["render",u]]);export{y as __pageData,C as default};
